//! 図鑑の読みもの。個別の紹介、なかまのしくみ、時代、証拠を分けて読む。
//! 日本語の追加本文は ja(...) で明示し、読み辞書の検査にも含める。
use crate::lang::Lang;
use crate::life::{self, Art, SPECIES, PHENOMS};

pub struct Section {
    pub title: &'static str,
    pub body: String,
}

fn ja(text: &'static str) -> &'static str { text }

fn local(text: crate::lang::L, language: Lang) -> &'static str {
    match language { Lang::Ja => text.0, Lang::En => text.1, Lang::Zh => text.2 }
}

pub fn sections(e: usize, language: Lang) -> Vec<Section> {
    let (desc, fact) = if e < SPECIES.len() {
        (local(SPECIES[e].desc, language), local(SPECIES[e].fact, language))
    } else {
        (local(PHENOMS[e - SPECIES.len()].desc, language), "")
    };
    let mut result = vec![Section {
        title: match language { Lang::Ja => "まずは知ろう", Lang::En => "Meet this entry", Lang::Zh => "先来认识" },
        body: if fact.is_empty() { desc.to_string() } else { format!("{}\n\n{}", desc, fact) },
    }];
    // 英語・中国語は既存の翻訳を維持。追加の読みものは日本語版。
    if language != Lang::Ja { return result; }
    if e < SPECIES.len() {
        let sp = &SPECIES[e];
        if let Some(text) = individual(sp.slug) {
            result.push(Section { title: "ここに注目", body: text.to_string() });
        }
        result.push(Section { title: "なかまの体とくらし", body: profile(sp.art, sp.slug).to_string() });
        result.push(Section { title: "この時代の地球", body: era(life::entry_period(e)).to_string() });
        result.push(Section { title: "化石から考えよう", body: evidence(sp.art).to_string() });
    } else {
        result.push(Section { title: "しくみをたどろう", body: phenomenon(PHENOMS[e - SPECIES.len()].slug).to_string() });
        result.push(Section { title: "証拠をくらべよう", body: ja("昔の景色を直接見ることはできません。研究者は、地層の重なり、岩石の種類、そこに入った化石を組み合わせて、当時の環境を考えます。たとえばサンゴの化石と砂漠の砂岩では、示す環境がちがいます。ひとつの証拠だけで決めず、別の方法の結果が合うかを確かめます。\n\n地層の年代は、火山灰にふくまれる鉱物の放射性元素が、決まった速さで別の元素に変わる性質などを使って調べます。ただし年代には測定の幅があり、図鑑の景色もある一日の写真ではありません。地図の時代を前後に動かし、海岸線や緑の分布がどう変わるか比べてみましょう。変化の速さも、原因を考える手がかりになります。\n\n同じころに二つの出来事が起きても、一方がもう一方の原因とはかぎりません。原因を考えるには、起きた順序と、その間をつなぐしくみが必要です。考えてみよう。気候の変化を確かめるなら、陸の植物と海の化石から、どんな別々の手がかりを集められるでしょうか。自分の説明と合わない証拠にも目を向けると、より確かな復元へ近づけます。").to_string() });
    }
    result
}

fn profile(art: Art, slug: &str) -> &'static str {
    if slug == "prototaxites" { return ja("幹のように見えるものが、必ず木とはかぎりません。プロトタキシーテスの内部には細い管が集まっていて、木の年輪や葉とはちがうつくりをしています。大きな菌類だったという説が有力ですが、どんな生物だったか、何を栄養にしたかには研究が続いています。\n\n菌類は植物のように光から栄養をつくるのではなく、まわりの有機物などから栄養を取りこみます。陸の生態系を考えるときは、緑の植物だけでなく、枯れたものを分解し、土の中の物質をめぐらせる生物にも目を向けてみましょう。"); }
    match art {
        Art::Stromatolite | Art::Mat => ja("ぬるぬるした薄い膜の中にも、小さな生きものの世界があります。微生物マットは、たくさんの微生物が集まったものです。その一部は太陽の光を使い、水と二酸化炭素から栄養をつくります。このはたらきを光合成といいます。酸素を出す光合成は、地球の海と大気を長い時間をかけて変えました。\n\nストロマトライトは生物そのものの骨ではなく、微生物の活動と泥のたまり方などがつくる層のある構造です。古い層状の岩がすべて同じ微生物によるとはかぎらず、最も古い例の解釈には議論もあります。酸素も、できるとすぐ空にたまったわけではなく、海の鉄などとの反応で使われました。生物のはたらきと地球の変化は、ひとつの長い物語なのです。"),
        Art::Trilobite { .. } | Art::Agnostus => ja("三葉虫は、背中のかたい殻が縦に三つの部分に分かれることから名づけられました。体には頭・胸・尾の区別があり、節のある脚は殻の下に並んでいました。大きくなるときは古い殻をぬぐ脱皮が必要です。化石でたくさん見つかる殻の中には、死んだ体だけでなく、ぬけがらもあります。\n\n目の形や大きさ、体を丸められるか、とげのつき方は種類ごとにちがいます。複眼とは、小さな目がたくさん集まった目のことです。ただし、目がない種類もいます。海底を歩く、泥にもぐる、水中を泳ぐなど、三葉虫全体には多様なくらしがありました。ひとつの種類の復元を、すべての三葉虫の生活に当てはめないことが大切です。"),
        Art::Radiodont(_) => ja("放射歯類は、頭の前の一対の付属肢と、口のまわりの板、体の左右に並ぶひれ状の部分が特徴です。付属肢は、口の近くで食べものをあつかう道具のようなものです。太いとげでつかむ形も、細かい突起で水中の小さな粒をこし取る形もあり、全員が同じ獲物を追ったわけではありません。\n\n節足動物の進化を考えるうえで重要な仲間ですが、現在のエビそのものではありません。脚や頭の部品がどのように組み合わさってきたかを、化石の特徴から調べます。大きな目や口があっても、それだけで狩りのしかたは決まりません。付属肢が曲がる範囲、口のつくり、体の動かし方を組み合わせ、できる動作と難しい動作を比べるのです。"),
        Art::Hallucigenia | Art::Aysheaia | Art::Kerygmachela | Art::Opabinia => ja("やわらかい体に脚やひれが並ぶ姿は、現在の動物の分類だけでは説明しにくいことがあります。節足動物に近い古い仲間を比べると、関節のある脚やかたい殻が、どんな順序で進化したのかを考えられます。進化は一直線の階段ではなく、枝分かれする木のようなものです。\n\n頭と尾、背中とおなかの見分けさえ、化石の研究で変わることがあります。押しつぶされた標本では、下側の脚が上側のとげのように見えることもあるからです。たくさんの標本をちがう向きから調べ、小さな爪や口の位置まで確かめると、復元の確かさが高まります。ふしぎな形を笑うだけでなく、その形でどう動けたか想像してみましょう。"),
        Art::Marrella | Art::Leanchoilia | Art::Fuxianhuia | Art::Sidneyia | Art::Isoxys | Art::Halkieria | Art::Wiwaxia => ja("体を守る板、とげ、節のある脚などは、古い海でくらす生きものの大切な手がかりです。かたい部分は敵から身を守るのに役立つことがありますが、重さが増すと動きにも影響します。左右の脚がちがう仕事をするのか、前の部分で食べものを集めるのか、体の部品を分けて見てみましょう。\n\n似た見た目でも、同じ仲間とはかぎりません。研究者は、表面の輪郭だけでなく、脚の枝分かれや口のまわりのつくりを比べます。上の紹介にある分類にも注目してください。カンブリア紀の動物には、現在の大きな分類群に近くても、その特徴をすべては持たないものがいます。そのような化石が、体のつくりの進化を知る空白をうめてくれます。"),
        Art::Eurypterid(_) | Art::Limulid => ja("ウミサソリやカブトガニの仲間は、はさみや脚のつくりから、クモに近い大きなグループに入ります。ウミサソリという名前でも、海だけにいたわけではありません。水の塩分が変わる入り江や、淡水の環境を利用した種類も知られます。水かきのような脚と、歩くための脚を比べてみましょう。\n\n脚の形からは泳ぎ方や食べ方の候補を考えられますが、化石の近くにいた動物を、そのまま獲物だったと決めることはできません。また、カブトガニに似た姿が長く続いていても、進化が止まったわけではありません。体の形が大きく変わらないことと、種や生態、遺伝的な性質が変わらないことは別なのです。"),
        Art::Arthro(_) | Art::Griffinfly => ja("節足動物は、体の外側に殻があり、脚に節を持つ動物です。陸では、乾燥から体を守ることと、空気から酸素を取りこむことが課題になります。昆虫には気管という細い管で空気を体内へ運ぶしくみがあり、クモやヤスデなどとは体の区切りや脚の数もちがいます。\n\n古い時代に大型の節足動物がいた理由には、酸素の量、気温、成長のしかた、敵や食べものなどが関係したと考えられます。「酸素が多いから大きい」というひとつの説明だけで、全種類を説明することはできません。翅のあるもの、地面を歩くもの、湿った場所にかくれるものを比べ、体の大きさと生活場所の組み合わせに注目しましょう。"),
        Art::Sponge(_) | Art::Archaeocyath => ja("海綿の仲間は、岩のように見えても動物です。体にたくさんの小さな穴があり、水を取りこんで、流れの中の細かな食べものを集めます。ふつうの動物のような口や胃がなくても、水を通すしくみでくらせるのです。古杯類も海綿に近い動物と考えられ、古い海の礁をつくる役割を担いました。\n\n海の中の盛り上がりである礁は、ほかの生物のすみかにもなります。ただし、図鑑には分類が議論されてきた海綿状の生物もふくまれます。穴の配置や体を支える細い骨片の形は、分類や水の流れを考える手がかりです。すべての空洞を水の通り道と決めず、化石に残る細部と比べる必要があります。"),
        Art::Coral(n) if n != 2 => ja("サンゴは植物ではなく、イソギンチャクに近い動物です。小さな体がつくる骨格が残り、ひとつずつでくらすものと、多くの個体がつながる群体をつくるものがあります。化石の断面に見えるしきりや細かな管は、サンゴの種類を見分ける手がかりです。\n\n古生代の四放サンゴや床板サンゴは、現在の海で礁をつくるサンゴと同じグループではありません。現在の造礁サンゴには、体内の藻類と栄養をやり取りするものが多いですが、古い化石のサンゴがすべて同じしくみだったとはいえません。暖かさだけでなく、水の深さ、濁り、海水の性質も、礁のできる場所を左右します。"),
        Art::Coral(_) | Art::Graptolite => ja("小さな個体が集まって、大きな枝や網のような形をつくる動物がいます。コケムシや筆石の仲間は、そのような群体を考えるよい例です。ひとつの穴や小部屋に一個体が対応することがあり、全体をひとつの大きな動物のように見るだけでは、体のしくみを見落とします。\n\n海底にくっつくものと、水中を漂うものでは、化石の広がり方もちがいます。広い海に分布し、短い期間で形が変わった種類は、離れた土地の地層の年代を比べるのに役立ちます。これを示準化石といいます。ただし、その化石が見つからないことだけで、地層の時代を決めることはできません。保存されやすさや当時のすみかも確かめます。"),
        Art::Crinoid | Art::Starfish | Art::Urchin => ja("ウミユリ、ヒトデ、ウニは、姿がちがっても棘皮動物という仲間です。体に五方向のまとまりが見えるものが多く、管足という小さな器官を、水の圧力を使って動かします。ウミユリの腕は水中の食べものを集め、ヒトデやウニには海底を動き回る種類が多くいます。\n\n死んだあとに体をつなぐやわらかい部分が失われると、骨のような小さな板がばらばらになります。だから完全な姿の化石と、砂の中のかけらでは、分かることがちがいます。古い棘皮動物には現在と異なる対称性のものもあり、名前の「ユリ」「リンゴ」に引っぱられず、口や腕、体を支える部分のつながりを見ましょう。"),
        Art::Brachiopod => ja("二枚の殻があるので二枚貝に似ていますが、腕足動物は別の仲間です。殻は主に背側と腹側に対応し、二枚貝の左右の殻とは組み合わせがちがいます。多くは海底にすみ、体内の触手のある器官で水中の細かい食べものを集めます。\n\n殻のふくらみやしわ、体を固定する部分の形は、海底での生活を考えるヒントです。形が似ることと、祖先が近いことは同じではありません。似た環境で別々の仲間が似た形になることを収斂といいます。腕足動物と二枚貝を比べると、分類には外見のほかに、体の内側のしくみも必要なことが分かります。"),
        Art::Cephalopod(_) | Art::Nectocaris => ja("頭足類には、イカ、タコ、オウムガイなどがいます。足にあたる部分が頭の近くに集まり、水を噴き出して移動するものが多い仲間です。殻のある化石では、部屋を分けるしきりや、それらをつなぐ構造が見つかり、浮き沈みを調節するしくみを考える手がかりになります。\n\nまっすぐな殻と巻いた殻では、水の抵抗や体の向きの保ち方がちがいます。ただし殻の大きさだけから泳ぐ速さや狩りのしかたを決めることはできません。頭足類との関係が議論される化石もあるので、個別の紹介の分類にも注目しましょう。殻の中の部屋の数は、毎年ひとつずつ増えるとはかぎらず、そのまま年齢にはなりません。"),
        Art::Mollusc(2) | Art::Fusulinid | Art::Radiolarian => ja("小さな殻や骨格にも、海の大きな歴史が記録されています。フズリナやヌンムリテスは有孔虫という単細胞の生物で、放散虫も小さな生物の仲間です。一個の細胞でも、複雑な部屋や網目を持つ構造をつくれます。見た目が貝に似ていても、貝の仲間とはかぎりません。\n\n殻が大量に積もると、石灰岩やチャートなどの岩石の材料になります。殻の成分や形、ほかの化石との組み合わせから、海水の性質や地層の年代を考えます。ただし水中を漂うものと海底にすむものでは示す環境がちがいます。大きさが小さいことと、地球の物質のめぐりで果たす役割が小さいことは、別なのです。"),
        Art::Mollusc(_) | Art::Slug => ja("貝の仲間は、やわらかい体と、それをおおう外套膜という部分を持ちます。外套膜が殻をつくりますが、殻が目立たない種類もいます。二枚貝にはえらで水中の粒を集めるものが多く、巻貝には表面をけずるもの、獲物を食べるものなど、さまざまな食べ方があります。\n\n殻の厚さ、穴のあと、表面の成長線を比べると、身を守るしくみや成長を考えられます。しかし成長線が必ず一年を表すわけではありません。殻があった向きのまま埋まったのか、波や流れで運ばれたのかによっても、化石の読み方は変わります。殻だけの標本と、まわりの地層を合わせて観察することが大切です。"),
        Art::Trace => ja("足あとや巣穴、はい回ったあとは、生きものの体そのものではなく、活動の記録です。これを生痕化石といいます。骨のない生きものでも、泥の上や中に動いたあとを残すことがあります。体の化石がない場所でも、そこに生物がいたと分かるのです。\n\n道の曲がり方や枝分かれ、穴の深さを調べると、食べものを探したのか、すみかをつくったのかを考えられます。ただし同じ生物がちがうあとをつくることも、ちがう生物が似たあとをつくることもあります。生痕の名前は、そのまま作り主の種の名前ではありません。泥を掘る活動は海底をかきまぜ、水と酸素の入り方も変えました。"),
        Art::Tubes | Art::Worm | Art::Jelly | Art::Tully => ja("やわらかい体の生きものは、死ぬと形がこわれやすく、ふつうは化石に残りにくいものです。それでも、細かい泥に早く埋まるなどの条件がそろうと、口や消化管、細い突起のあとが残ることがあります。体の形を知るには、かたい骨がある生物ばかりを見ていては足りません。\n\n筒のあるもの、虫のようなもの、平たいものが、みな近い仲間とはかぎりません。上の紹介で、どの部分が見つかっているかを確かめましょう。輪郭だけでは分類が難しい標本もあります。海底に伏せていたのか、水中を動いたのかを考えるには、体の左右や上下の区別、筋肉や付属肢の配置など、複数の証拠が必要です。"),
        Art::Fish(_) | Art::Jawless(_) => ja("魚に似た形を見つけたら、口と体の支えに注目しましょう。初期の脊索動物には、体を支える脊索という棒状の構造がありました。脊椎動物はその仲間の一部です。古い種類にはあごがなく、水といっしょに食べものを取りこんだり、底の粒を集めたりしたと考えられるものがいます。\n\nあごのない魚でも、かたいよろいを持つもの、ひれの目立つもの、口の形が特殊なものなど多様です。あごがないことは、単純で役に立たないという意味ではありません。現在にもヤツメウナギなどの仲間がいます。体の支え、えら、目、ひれがどのように組み合わさったかを比べると、脊椎動物の進化を枝分かれとして理解できます。"),
        Art::Placoderm(_) => ja("板皮類には、頭や胸をかたい板でおおう魚が多くいます。あごを使って食べものをとらえますが、歯やあごの形は種類によってちがいます。大きな捕食者ばかりでなく、海底近くでくらすものや、別の食べ方をしたと考えられるものも知られています。\n\n頭の板がよく残っても、胴体の後ろは十分に分からないことがあります。部分的な化石から全長を求めるときは、近い仲間の体の割合を使うため、推定に幅が生まれます。板皮類は、あごのある脊椎動物の初期の進化を考える重要な化石です。よろいの形だけでなく、口の骨や胸びれの位置、子どもを残すしくみの証拠にも研究が広がっています。"),
        Art::Shark(_) | Art::RayFin => ja("水中を進む魚は、尾やひれで水を押し、体の向きを調節します。サメなどの軟骨魚類と、条鰭類をふくむ硬骨魚類では、骨格やひれの支え方が異なります。歯の形や口の向きは、何を食べたかを考える入口ですが、現在の魚とそっくりに生活したとはかぎりません。\n\nサメの歯は何度も生え替わり、歯だけが多く化石になります。そのため歯の数と生きていた個体の数は同じではありません。ほかの魚でも、うろこや耳石という小さなかたい部分が大切な資料になります。よく残る部品と残りにくい部品のちがいが、私たちの知る古い海の姿に影響することを覚えておきましょう。"),
        Art::LobeFin(_) => ja("肉鰭類のひれには、内側に太い骨と筋肉があります。そのうち四肢動物に近い仲間では、胸びれの骨を上腕、前腕などと対応させて調べられます。これは、魚がある日突然、完成した足を手に入れたという話ではありません。体を支えるしくみや頭の動かし方が、少しずつ組み合わさって変わったのです。\n\n浅い水の中で体を支えることは、陸を歩くことと同じではありません。息のしかた、肋骨、背骨、骨盤のつながりも重要です。ひれと足の中間の特徴を持つ化石があっても、その種類が人の直接の祖先だと証明されたわけではありません。近い枝の化石から、祖先の持っていた特徴を推定するのです。"),
        Art::Tetrapod(4 | 8 | 10) | Art::Mammal(3) => ja("ディメトロドンや獣弓類、キノドン類などは、哺乳類につながる側の単弓類を考える手がかりです。頭骨の目の後ろにある穴や、あごと歯のつくりを比べます。恐竜に似た見た目でも、分類は体の特徴と共通の祖先に基づいて決めます。\n\n長い時間の中で、食べものを細かく処理する歯や、あごを動かす筋肉のつき方が変化しました。哺乳類のあごと耳の進化では、古い仲間であごを支えていた小さな骨と、耳の骨との対応が重要です。ただし、その変化はどの種類でも同じ速さで進んだわけではありません。特徴の組み合わせを比べて、枝分かれの順序を考えます。"),
        Art::Tetrapod(_) => ja("四肢動物という仲間には、両生類、爬虫類、鳥類、哺乳類と、その古い近縁の生物がふくまれます。祖先が手足を持っていても、ヘビのように進化の過程で目立つ脚を失ったものがいます。分類では、現在の見た目だけでなく、どの祖先を共有するかが大切です。\n\n水から離れてくらすには、体重を支えるだけでなく、乾燥を防ぎ、呼吸し、子どもを残す必要があります。羊膜類では、胚を包む膜などのしくみが発達しました。一方、四肢動物の初期には、水中で役立つ指や手足を持つ種類もいました。「足があるから陸だけの生活」と決めず、背骨、肋骨、尾、化石の出た地層を合わせて考えましょう。"),
        Art::Plant(_) => ja("植物は光合成で栄養をつくり、食物網の土台になります。陸に広がるには、体の水を失わないこと、光に向かって体を支えること、次の世代を残すことが課題でした。根、茎、葉、水や養分を運ぶ管は、すべての植物に同じようにそろっているわけではありません。\n\n胞子でふえる植物と種子をつくる植物、花を持つ植物と持たない植物を比べましょう。種子は胚を守り、栄養をたくわえるしくみです。花粉を使う受粉は、受精のために外の水を必要とするしくみとは異なります。大きな木でも現在の木と幹のつくりがちがうことがあります。葉の形だけでなく、幹の断面、根、胞子や花粉も、進化と環境を調べる資料になります。"),
        Art::Dino(_) => ja("恐竜は、骨盤や脚などに共通の特徴を持つ爬虫類の仲間です。脚を体の下に置く姿勢は、体を支えて歩くしくみに関わります。鳥も恐竜の一部なので、恐竜の歴史は現在まで続いています。一方、同じ時代の翼竜や魚竜、首長竜は、それぞれ別の仲間です。\n\n歯やくちばし、首の長さ、前脚の形は、食べものの取り方や移動のしかたを考える材料です。似た特徴が別の枝で進化する場合もあり、ひとつの特徴だけでは系統は決まりません。また、すべての恐竜が同じ体温や成長の速さだったと決めることもできません。骨の内部、足あと、卵、皮膚や羽毛の印象などを合わせて、種類ごとの生活を調べます。"),
        Art::Marine(5 | 7 | 8) => ja("カメの甲羅は、体にのせたよろいではありません。背骨や肋骨などと結びついた骨格の一部で、背中側の甲とおなか側の甲が体を守ります。海、川、湖、陸にくらす仲間では、手足の形や甲羅の重さのバランスがちがいます。\n\n水中にすむカメも肺で空気を吸います。泳ぐためのひれ状の手足があるからといって、魚と同じ呼吸をするわけではありません。化石の甲羅だけでも特徴を比べられますが、頭や手足が見つかると食べ方や生活場所を考える資料が増えます。現在の近縁種の生活は参考になりますが、そのまま昔の種類に当てはめず、地層の証拠と確かめます。"),
        Art::Marine(_) => ja("海にくらした爬虫類は、水中で動くための体を陸の祖先から進化させました。魚竜、首長竜、モササウルス類は別々の仲間で、同じ「海の爬虫類」でも、尾や手足の使い方がちがいます。魚に似た流線形は、水の抵抗を減らすのに役立つ形が別々に進化した例です。\n\n肺で空気を吸うので、水中にずっと沈んだままではくらせません。子を体内で育てて産んだ証拠が見つかる仲間もいます。ただし、どの種類も同じ繁殖をしたと決めることはできません。ひれの骨の配置、尾の形、胃の内容物などを使って、泳ぎ方や食べ方を調べます。体形の似たイルカとの比較では、共通点だけでなく骨格のちがいにも注目しましょう。"),
        Art::Pterosaur(_) => ja("翼竜の翼は、長く伸びた手の第四指などに支えられた皮膜です。鳥は主に羽毛で翼をつくり、コウモリは複数の指で皮膜を広げます。同じ空を飛ぶ脊椎動物でも、翼の骨の組み立てはちがうのです。翼竜は恐竜に近い仲間ですが、恐竜そのものにはふくめません。\n\n軽い骨は飛ぶのに有利ですが、化石に残る途中でこわれやすくもなります。翼を広げた幅、体重、離陸のしかたの推定には、骨の強さや筋肉、空気の力を使います。大きなとさかがあっても、その目的を見た目だけで確定はできません。仲間への合図などの仮説を、成長による形の変化や近縁種との比較で検討します。"),
        Art::Bird(_) => ja("鳥は獣脚類という恐竜の一群から進化しました。羽毛は飛ぶためだけの道具ではなく、体を温めることや合図などにも役立ちます。飛べない鳥、海を泳ぐ鳥、地上で走る鳥もいて、翼があることと、空を飛ぶことは同じではありません。\n\n腕や肩の骨、羽毛の配置、胸の筋肉がつく場所を比べると、どんな運動ができたかを考えられます。化石の鳥に歯や長い骨の尾が見つかることもあり、現在の鳥の特徴が一度にそろったわけではないと分かります。ペンギンと海を泳ぐ別の鳥のように、近い形が別々に生じることもあります。似たくらしと、祖先の近さを分けて考えるのが系統の研究です。"),
        Art::Mammal(_) => ja("哺乳類は、乳で子を育てる仲間です。毛や乳のようなやわらかい部分は化石に残りにくいので、古い種類の研究では、あご、耳、歯の特徴が大切です。切る歯、引き裂く歯、すりつぶす歯のちがいから、食べものを口の中でどう処理したか考えられます。\n\n歯が似ていても、まったく同じ物を食べたとはかぎりません。歯の細かなすりへりや、骨に残る元素の割合などを組み合わせて調べます。また、哺乳類の歴史は小さな動物が順に大きくなる一本道ではありません。木に登る、地面を走る、空を飛ぶ、水に戻るなど、枝分かれした仲間が異なる環境を利用しました。近縁関係と生活の似かよりを分けてみましょう。"),
        Art::Archosaur(_) => ja("ワニやその近い仲間を調べると、中生代の陸や水辺には、恐竜以外にもさまざまな爬虫類がいたことが分かります。現在のワニの姿だけを基準にせず、脚の長さ、歯、背中の板、首のつくりを比べましょう。陸をよく歩いた仲間や、独特な食べ方をした仲間もいます。\n\n頭骨の穴や足首など、見た目では目立ちにくい特徴が分類に役立ちます。長い鼻や大きな体が同じでも、近縁とはかぎりません。この図鑑の復元画像には形を見やすくまとめた部分もあるため、分類の説明と分けて読むことが大切です。ひとつの骨から生活の全部を決めず、骨格全体と、化石が見つかった水辺や陸の地層を合わせて考えます。"),
    }
}

fn evidence(art: Art) -> &'static str {
    match art {
        Art::Plant(_) => ja("葉の化石は、葉がついていた木の全体とはかぎりません。葉・幹・根・種子が別々に見つかると、それらが同じ植物のものか確かめる必要があります。花粉や胞子は小さく広く運ばれ、森林の変化を追う資料になりますが、たくさん見つかる量がそのまま木の本数を表すわけではありません。\n\n葉の形や年輪、近い現生植物の性質を組み合わせると、昔の気温や雨の量を推定できます。これを古気候の復元といいます。ただし、近い仲間が昔も同じ環境にいたとはかぎらず、別の証拠との比較が必要です。考えてみよう。この植物が消えたら、食べる動物、日かげにすむ動物、土の水分にはどんな変化が起こるでしょうか。"),
        Art::Trace => ja("あとが残った地面は、そのときの行動を記録しています。足あとが続けば歩幅を、巣穴なら泥のかたさや掘り方を考えられます。一方で、あとができたときの水分や、その後の侵食で形が変わることもあります。足あとの大きさから体重や速さを出す計算にも、仮定と誤差があります。\n\n研究では、現在の動物が砂や泥につくるあとと比べたり、実験で似た形ができる条件を調べたりします。考えてみよう。同じ一本の線に見えるあとでも、体を引きずった場合と、泥の中を食べ進んだ場合では、どんなちがいが残りそうでしょうか。答えをひとつに急いで決めず、たしかめる方法も考えると、化石を見る目が深まります。"),
        _ => ja("化石は、昔の生きものの全部が同じ割合で残った記録ではありません。骨や殻は残りやすく、皮膚や内臓は残りにくいものです。埋まる速さ、水の酸素、あとから受ける熱や圧力によっても保存は変わります。生きものが死んでから化石になるまでの過程を調べる研究を、タフォノミーといいます。\n\n形から考えた食べ方は仮説です。胃の内容物、ふんの化石、かみあと、歯のすりへりなど、別の証拠と合えば確かさが増します。図の色、鳴き声、細かな行動には分からない部分が残ります。考えてみよう。この生きものの骨や殻がひとつだけ見つかったら、何が言え、何はまだ言えないでしょうか。証拠と想像の境目を説明できることも、図鑑を読む大切な力です。"),
    }
}

fn era(period: usize) -> &'static str {
    match period {
        0 => ja("カンブリア紀の海では、体のつくりが異なる動物が化石記録の中で目立つようになります。カンブリア爆発と呼ばれますが、一日の出来事でも、生命の最初の誕生でもありません。それ以前にも生物がいて、変化は長い時間にわたりました。\n\n食べる・食べられる関係、海底を掘る活動、殻やとげによる防御が、海のくらしを複雑にしました。バージェス頁岩や澄江のようにやわらかい体まで残る産地は、殻だけでは分からない世界を見せてくれます。同じ時代の動物でも、泳ぐもの、海底を歩くもの、水をこすものでは、食物網での役割がちがいます。"),
        1 => ja("オルドビス紀には、海の生物がさらに多様になり、腕足動物、コケムシ、棘皮動物などが多くの海底に広がりました。カンブリア紀に現れた体のつくりをもつ仲間が、さまざまな生活場所を利用していった時代です。生物の種類が増えることを、多様化といいます。\n\n紀の終わりには氷床が広がり、海面や気候が変化して大きな絶滅が起こりました。浅い海の面積が減ることは、そこにすむ生物のすみかを減らします。ただし絶滅はひとつの瞬間に全部が消えたという意味ではなく、複数の段階や環境変化を地層から調べる必要があります。"),
        2 => ja("シルル紀には、前の時代の絶滅のあと、海の生態系が回復していきました。あごのある魚の記録が増え、海では礁も発達します。陸上では、小さな植物や節足動物の化石が、海から離れた場所の生活を考える手がかりになります。\n\n陸に出ることは、ただ水辺から歩き出すだけではありません。水を失わずに呼吸し、体を支え、子孫を残さなければなりません。小さな植物が生えると、地面の水分や日かげ、土のでき方が変わります。生物が環境に合わせるだけでなく、生物自身も次の生物がくらす環境を変えていくのです。"),
        3 => ja("デボン紀は多様な魚が栄えた時代で、よく「魚の時代」と呼ばれます。海には板皮類やサメの仲間などがいて、陸では森林が発達しました。四肢動物に近い魚や、指を持つ初期の四肢動物も、この時代の進化を知る資料です。\n\n森林の根は岩石を風化させ、土をつくり、川が海へ運ぶ物質にも影響します。海の変化と陸の緑は別々の話ではありません。紀の後半には複数の絶滅の出来事があり、海の酸素不足や気候など、いくつもの要因の関係が研究されています。大きな進化の変化と、絶滅が同じ時代に進んだことに注目しましょう。"),
        4 => ja("石炭紀には、低緯度の湿地に大きな森林が広がりました。枯れた植物が水の多い場所にたまり、分解されにくい条件で埋まると、長い時間のあとに石炭の材料になります。いま燃料に使う炭素の一部は、昔の植物が空気から取りこんだものです。\n\n一方、地球全体が湿った森だったわけではありません。南の大陸では氷床が発達し、海面も変動しました。空気中の酸素は現在より多かった時期があると推定されますが、大型の昆虫の出現をそれだけで説明はできません。森林の縮小や乾燥化は、湿地に頼る生物と、乾いた場所を利用できる生物に異なる影響を与えました。"),
        5 => ja("ペルム紀には超大陸パンゲアが広がり、内陸では海の湿った空気が届きにくい場所が増えました。乾燥した環境に適した植物や、単弓類などが陸上で多様化します。ただし緯度や地形で気候は異なり、すべての土地が砂漠だったわけではありません。\n\n紀の終わりには、地球史上最大級の大量絶滅が起こりました。シベリアの大規模な火山活動に関連した温暖化、海の酸素不足などが重要だと考えられています。絶滅した種類の割合と個体数の割合は別です。生き残った仲間が、その後の世界でどのように広がったかも、絶滅と同じくらい大切な研究テーマです。"),
        6 => ja("三畳紀は、ペルム紀末の大量絶滅のあとに生態系が組み直された時代です。恐竜、翼竜、哺乳類につながる仲間などが現れましたが、はじめから恐竜だけが陸を占めていたわけではありません。ワニに近い仲間など、多様な動物が共存していました。\n\nパンゲアの内陸では乾燥しやすく、地域によって季節性の強い気候もありました。紀の終わりには中央大西洋の大規模な火山活動と関連する絶滅が起こります。あるグループが後に栄えたことは、最初から他の動物より必ず優れていたという意味ではありません。環境の変化と偶然も、進化の歴史に関わります。"),
        7 => ja("ジュラ紀にはパンゲアの分裂が進み、大陸の間に新しい海が開いていきました。陸では恐竜が多様化し、海ではアンモナイトや海生爬虫類がくらしていました。森林には針葉樹やシダ、イチョウの仲間などが見られます。\n\n大陸が分かれると、生物が移動できる道も変わります。別れた集団が異なる進化をたどることもあり、似た化石が離れた大陸にある理由を地図から考えられます。ただし、陸がつながっていても砂漠や山、気候が移動を妨げることがあります。大陸の形だけでなく、その上に広がる環境を見ることが大切です。"),
        8 => ja("白亜紀には花をつける被子植物が多様化し、陸上の食べものやすみかが変化しました。昆虫による受粉は被子植物以前にもあり、花と虫の関係がゼロから突然始まったわけではありません。海面が高い時期には、大陸の内部まで浅い海が入りこみました。\n\n紀末の約6600万年前には小惑星衝突が起こり、鳥以外の恐竜やアンモナイトなどが絶滅しました。日光が減ると、植物や植物プランクトンの生産が下がり、それを食べる生物にも影響が広がります。大きな体だけが原因ではなく、食べものや生活場所など、生態のちがいが生き残りに関わりました。"),
        9 => ja("古第三紀には、白亜紀末の絶滅を生き残った哺乳類や鳥などが多様化しました。哺乳類はこの時代に初めて誕生したのではなく、恐竜と同じ中生代にもすでにくらしていました。クジラの祖先が水中生活へ進むなど、生活場所の大きな変化も見られます。\n\n温暖な時期の南極には森林があり、現在の氷の景色とはちがっていました。その後の寒冷化や南極の氷床の発達は、海流や大気、森林の分布に影響しました。化石の歯や葉を現在の生物と比べるだけでなく、地層や化学的な記録も組み合わせると、気候と生物の変化の前後関係を調べられます。"),
        10 => ja("新第三紀には、地域ごとに森林や草原の分布が変わり、走る草食獣やそれを利用する捕食者が多様化しました。イネ科の植物はそれ以前にもあり、世界中でいっせいに草原が始まったわけではありません。雨の季節性、気温、火災、動物による採食などが景色を左右します。\n\n草をよく食べる動物の歯には、すりへりに耐える特徴が見られることがあります。ただし砂や土ぼこりも歯をすり減らすため、歯の高さだけで食べものを断定できません。人類に近い仲間の進化も、多様な環境の中で進みました。「森から出て一直線に人になった」という単純な物語にはできないのです。"),
        _ => ja("第四紀には、氷床が広がる氷期と、その間の比較的暖かい時期がくり返されました。地球の軌道や地軸の傾きの変化で日光の届き方が変わり、氷や温室効果ガスのはたらきも加わって、気候の変化が増幅されました。氷期でも、地球全体が氷でおおわれたわけではありません。\n\n海面が下がると、海だった場所が陸になり、生物や人が移動できる道が変わりました。大型動物の絶滅は地域で時期が異なり、気候変化と人の活動などの影響を個別に調べる必要があります。この図鑑が扱う過去の世界から、現在の生物の分布や、人と自然の関係につながる問いを見つけてみましょう。"),
    }
}

fn individual(slug: &str) -> Option<&'static str> {
    Some(match slug {
        "anomalocaris" => ja("大きな目と頭の前の付属肢は、周囲を見ながら食べものをとらえる生活を考える材料です。ただし、かたい三葉虫を何でもかみ砕く怪物のような姿は、確定した事実ではありません。口や付属肢の構造、動かせる範囲から、軟らかい獲物をどうとらえたかなどの研究が続いています。\n\n最初は別々の動物の一部と考えられた化石が、体全体の発見によってひとつにつながったことでも有名です。研究の進歩は、名前を覚えるだけでなく、部品がどのように結びつくかを確かめることから生まれます。"),
        "opabinia" => ja("五つの目と、先端で物をつかめそうな長い吻が目を引きます。吻とは、頭から前へ伸びた部分のことです。体の左右のひれ状の部分も合わせて、海底近くでどう動き、食べものを口に運んだかが議論されています。\n\n現在の動物のどれかに無理に当てはめると、重要な特徴を見落とします。節足動物に近い古い枝として考え、どの特徴を共有し、どの特徴を共有しないかを整理することが、系統を考える手がかりになります。"),
        "hallucigenia" => ja("背中にはとげ、おなか側には軟らかい脚が並びます。かつては上下や前後の解釈が異なる復元もありましたが、脚の爪や頭の細部を調べたことで理解が進みました。奇妙に見える姿にも、化石を読む歴史があるのです。\n\nカギムシなどとの関係を調べるときは、体の輪郭だけでなく、小さな爪の内部構造も比べます。肉眼で目立つ大きなとげより、顕微鏡でしか見えない細部のほうが、近縁関係を知る強い証拠になることがあります。"),
        "tiktaalik" => ja("魚のうろこやひれを持ちながら、平たい頭、動かせる首、体を支えるのに役立つ胸びれの骨などを備えていました。水中の生活の特徴と、四肢動物に近い特徴がひとつの体に見られます。\n\nこれは、完成した足で陸を走っていたという証拠ではありません。浅い水辺で体を持ち上げる動作と、陸上を歩く動作は区別する必要があります。化石が見つかった地層の環境と骨の構造を組み合わせると、ひれから手足への変化を具体的に考えられます。"),
        "dunkleosteus" => ja("よく残るのは頭と胸のよろいで、体の後ろまで完全な骨格がそろうわけではありません。そのため全長の復元には、近い仲間との比較や、頭と胴体の割合についての仮定が必要です。よく知られた巨大な復元像も、研究によって見直されます。\n\n食べものを切る鋭い部分は、ふつうの魚の歯が並んだものとは異なります。あごを開閉するしくみと、先端に力がかかるしくみを分けて考えると、体の大きさの話だけでは見えない捕食者としての特徴が分かります。"),
        "dimetrodon" => ja("背中の帆が目立ちますが、ディメトロドンは恐竜ではなく、哺乳類側の古い単弓類です。帆は背骨から上へ伸びた突起に支えられています。体温調節や仲間への合図などの役割が考えられてきましたが、目的をひとつに断定することはできません。\n\n名前の印象や復元図より、頭骨や歯、脚の特徴を比べると分類が分かります。恐竜が現れる前の陸にも、大きな捕食者と多様な草食動物による生態系があったことを教えてくれる生きものです。"),
        "archaeopteryx" => ja("羽毛のある翼を持つ一方、歯、長い骨の尾、手の爪なども備えています。現在の鳥らしい特徴と、ほかの恐竜に見られる特徴が組み合わさった化石です。鳥と恐竜のつながりを考えるうえで重要ですが、現在のすべての鳥の直接の祖先と決まったわけではありません。\n\n飛ぶ能力を考えるには、羽毛があるかだけでなく、肩の動き、翼の形、筋肉のつく場所を調べます。現在の鳥とまったく同じ飛び方をしたと考える前に、できる動きの範囲を化石と力学から確かめます。"),
        "homo-sapiens" | "homo-erectus" | "neanderthal" | "australopithecus" => ja("人類の進化は、ひとつの種類が順番に次へ変わる行列ではありません。いくつもの系統が枝分かれし、同じ時代に異なる人類がくらしたこともありました。直立二足歩行、脳の大きさ、道具の利用なども、全部が同時にそろったわけではありません。\n\n骨や歯に加え、石器、火のあと、生活した場所を調べると、行動を考える材料になります。ただし、石器と化石が近くにあるだけでは作り主を確定できないこともあります。古いDNAが得られる場合は、骨の形だけでは分からない集団間の関係や交流も研究できます。"),
        "southern-nothofagus" | "southern-podocarps" | "southern-araucarians" | "southern-ferns" | "australian-proteaceae" => ja("この項目は、ひとつの種が長く生き続けた記録ではなく、地域と時代によって顔ぶれの変わる植物群の代表です。南アメリカ、南極、オーストラリアの化石を比べると、大陸が近かったころのつながりや、その後の気候変化を考えられます。\n\n現在の南極に木がないからといって、昔もなかったとはいえません。一方、ある場所で木材が見つかっただけで、同じ時代の南極全体が森だったともいえません。葉、花粉、材の産地と年代をそろえ、局地的な森林と大陸全体の景色を区別することが重要です。"),
        _ => return None,
    })
}

fn phenomenon(slug: &str) -> &'static str {
    match slug {
        "gondwana" => ja("ゴンドワナは、現在の南アメリカ、アフリカ、南極、インド、オーストラリアなどにつながる陸の集まりです。地表は何枚ものプレートに分かれ、ゆっくり動きます。大陸は海の上を船のように漂うのではなく、プレートの運動とともに位置を変えます。\n\n離れた大陸で似た化石や同じ年代の岩石、氷河のあとが見つかることは、昔のつながりを考える証拠です。ただし海岸線をパズルのように合わせるだけでは不十分です。地層の年代や山脈の続きも比べて、大陸の復元を確かめます。"),
        "laurentia" => ja("ローレンシアは、現在の北アメリカの中心部などにあたる古い大陸です。現在の国境や海岸線が、そのまま古い大陸の境目だったわけではありません。時代によって浅い海が大陸の上まで広がり、海の生きものがくらす場所になりました。\n\n大陸の移動と海面の上下は別の現象ですが、どちらも海岸線を変えます。陸の内部で海の化石が見つかっても、その生物が陸で生活したという意味ではありません。地層と地図を合わせ、当時そこに海があった可能性を考えましょう。"),
        "euramerica" => ja("ユーラメリカは、ローレンシア、バルティカ、アヴァロニアなどの陸が近づき、衝突してできた大陸です。間にあった海がせばまり、衝突する境目では岩石が押され、山脈がつくられました。山は固定した地球の飾りではなく、大陸の運動の記録でもあります。\n\n陸どうしがつながると、生物が移動できる道が増えることがあります。一方、山脈は雨の降り方を変え、反対側を乾燥させる場合もあります。衝突は地図の輪郭を変えるだけでなく、気候や生物の分布にも影響するのです。"),
        "pangaea" => ja("パンゲアは、多くの大陸が集まってできた超大陸です。広い陸の内側には海からの水蒸気が届きにくい地域があり、気温の季節差や乾燥が大きくなりました。ただし、超大陸全体が同じ気候だったわけではありません。\n\n広くつながる陸は、生物が分布を広げる道になりますが、砂漠や高い山は移動の壁にもなります。その後に大陸が裂けると、離れた集団が別々に進化することもあります。地図でつながりを見たら、その上を生物が本当に通れそうか、環境も考えてみましょう。"),
        "laurasia" => ja("ローラシアは、パンゲアの分裂後の北側の大陸群を指します。現在の北アメリカ、ヨーロッパ、アジアに関係しますが、そのつながり方や海峡は時間とともに変わりました。大陸名は、ずっと同じ形の一枚の陸を意味するとはかぎりません。\n\n大西洋が開くと、新しい海底が中央部でつくられ、大陸どうしが離れていきました。似た恐竜や植物の化石がどこに出るかを、地図の変化と比べると、分布が分かれた理由を考えられます。海面の上昇で陸の道が水に沈むことにも注目しましょう。"),
        "eruption" => ja("マグマが地表に出ると溶岩と呼ばれます。冷えて固まった溶岩や火山灰は新しい地層をつくり、噴火の記録として残ります。噴火には、溶岩が流れ出るものと、火山灰を激しく噴き上げるものなどがあり、すべて同じ姿ではありません。\n\n火山は土地をつくるだけでなく、大気にも物質を送ります。二酸化炭素は長期の温暖化に、成層圏に達した硫黄を含む粒子は一時的な寒冷化に関わることがあります。噴火の大きさだけで結果は決まらず、ガスの種類、続く時間、放出される場所が重要です。"),
        "barren-land" => ja("大きな陸上植物が広がる前でも、陸がまったくの無生物だったと決まるわけではありません。微生物などの活動があっても、森林のようには景色に現れにくいものです。図の岩や砂は、当時の地表を分かりやすく表した復元です。\n\n根や厚い土が少ない地面では、水や風によって粒が運ばれます。植物が広がると、根が地面を支え、落ち葉や微生物が土のでき方を変えます。陸の緑化は、景色の色だけでなく、川の流れ方や海へ運ばれる栄養の量にも関わりました。"),
        "green-shore" => ja("小さな植物が陸に広がるには、乾燥を防ぎ、体を支え、次の世代を残すしくみが必要でした。はじめから大木の森があったわけではなく、湿った地面に低い植物が生える景色を考えることができます。\n\n植物の体だけでなく、胞子も古い陸上生活の証拠です。胞子は遠くまで運ばれるので、発見場所がそのまま植物の生えた場所とはかぎりません。根や茎がその場に残る化石と組み合わせると、どこにどんな植物が生えていたかを、より具体的に考えられます。"),
        "first-forest" => ja("背の高い植物が集まると、上で光を受ける場所と、下の日かげが生まれます。根は土を支え、落ち葉は小さな生物の食べものになります。森林は木の集まりであると同時に、光、水、栄養が立体的に分かれる生活空間です。\n\n初期の森林をつくった植物には、現在の木と異なる幹や根のしくみがありました。木になる方法が進化の中で複数生じたことを示します。その場に立った根や切り株の化石が見つかると、流されてきた幹だけでは分からない、木の間隔や森林の構造を調べられます。"),
        "coal-forest" => ja("湿地では地面の水が多く、落ちた植物が分解されにくい条件が生まれることがあります。植物がたまり、泥に埋まり、長い時間にわたって熱や圧力を受けると石炭になります。どんな森林でも、そのまま石炭になるわけではありません。\n\n石炭紀の湿地林には、鱗木やカラミテスなど、現在は小型の仲間が多い植物群の大きな姿がありました。高緯度の氷床の変動や海面の上下で、湿地と海がくり返し入れ替わる場所もありました。石炭の層の上下の岩石を見ると、森林だけでなく環境全体の移り変わりを読めます。"),
        "gymnosperm-forest" => ja("恐竜時代の森には、針葉樹、ソテツやイチョウの仲間、シダなどがありました。種子をつくる裸子植物と、胞子でふえるシダは、次の世代を残す方法がちがいます。花が目立たない森も、多様な植物の組み合わせでできています。\n\n葉や花粉の化石から、地域による植生のちがいを調べられます。図鑑の森は代表的な景観で、すべての時代と場所に同じ植物があったわけではありません。植物を食べる動物の歯やふんの化石と比べると、植物と動物をひとつの生態系として考えられます。"),
        "flowering-forest" => ja("被子植物は、胚珠が心皮に包まれ、種子ができると果実におさまる仲間です。花は繁殖に関わる器官で、目立つ花びらを持たない種類もあります。虫に花粉を運んでもらうものも、風を使うものもあり、花があることと虫に頼ることは同じではありません。\n\n昆虫と植物の関係は被子植物の登場以前からありました。白亜紀に被子植物が多様化すると、花、葉、種子、果実を使う生物との関係も変化していきます。花粉だけでは森の高さや色まで分からないため、葉、材、花そのものの化石などを組み合わせます。"),
        "cenozoic-forest" => ja("花や実をつける木々は、葉を食べる動物、果実を食べる鳥、木の上にすむ哺乳類などに、ちがう資源を与えます。動物が種子を運ぶこともあり、森林は植物が一方的に動物を支えるだけのしくみではありません。\n\n古第三紀には現在より温暖な時期があり、高緯度にも森林が広がりました。その後の気候の変化で、森の分布や構成も変わります。似た葉が見つかっても、一種類の木でできた森とはかぎりません。花粉、葉、幹の記録を比べ、地域と年代をそろえて森林を復元します。"),
        "cenozoic-grassland" => ja("草原が広がるかどうかは、雨の量だけでは決まりません。雨の降る季節、火災、草を食べる動物、土の性質などが関係します。イネ科の植物は新第三紀より前にもあり、世界中の森林がいっせいに草原になったわけではありません。\n\n草食獣の歯の高さやすりへり、土の中の植物由来の小さな粒、炭素の同位体などから、草原の広がりを調べます。同位体とは、同じ元素でも重さのちがう原子のことです。異なる光合成の方法を持つ植物の割合を調べると、動物の食べものと景色の変化をつなげて考えられます。"),
        "permian-desert" => ja("広い大陸の奥では、海からの湿った空気が届きにくくなります。山の風下側で雨が減ることもあります。乾燥した土地では、風が砂を運び、砂丘をつくります。岩石に残る斜めの縞は、砂丘が少しずつ動いたあとである場合があります。\n\n赤い地層には鉄の酸化が関係することが多いものの、赤い色だけで砂漠と断定はできません。砂粒の大きさや丸さ、堆積した模様、泥の割れ目、化石などを組み合わせます。乾燥への適応を調べるときも、地図の色だけでなく、水を利用できる場所や季節を考える必要があります。"),
        "hirnantian-ice" => ja("オルドビス紀末には、南極付近にあったゴンドワナに氷床が広がりました。陸に氷がたまると、海水の一部が陸上に保存され、世界の海面が下がります。浅い海が広かった時代には、海面の低下が多くの生物のすみかを変えました。\n\n寒冷化と海面低下、その後の温暖化や海の酸素の変化などを、地層から比べます。絶滅は「寒くなったから」の一言だけでは十分に説明できません。氷河が岩石を削ったあとと、海の化石の変化をつなぐことで、地球規模の出来事を考えられます。"),
        "gondwana-ice" => ja("石炭紀からペルム紀にかけての氷河時代には、ゴンドワナの高緯度に氷床が発達しました。現在は離れた大陸にある、同じ時代の氷河の堆積物や削りあとが、昔の大陸のつながりを示す証拠になります。\n\n氷床が増えたり減ったりすると、海面が動きます。低緯度の湿地に海が入りこむなど、遠くの環境にも影響が届きました。氷河と石炭の森は、別々の場所にありながらつながった現象です。同じ時代の地球に、寒い場所と暖かい場所が共存したことに注目しましょう。"),
        "quaternary-ice" => ja("雪が夏にもとけずに残り、長い時間にわたって押し固められると、陸をおおう氷床が成長します。氷床は止まった氷の板ではなく、ゆっくり流れ、岩を削り、削った粒を運びます。その跡は現在の地形にも残っています。\n\n地球の軌道や地軸の変化は、緯度や季節ごとに日光の配分を変えます。氷が日光を反射する効果や、温室効果ガスの変化も加わり、氷期と暖かい時期の変動が起こります。海の底の堆積物や氷の中の気泡は、古い気候や大気を調べる記録です。"),
        "siberian-traps" => ja("シベリアの大規模な火山活動は、一回の火山の爆発ではなく、広い地域で続いたマグマの活動です。噴き出すガスに加え、マグマが周囲の地層を熱したことによるガスの発生も研究されています。\n\n二酸化炭素の増加は温暖化につながり、暖かい海水は酸素を溶かしにくくなります。海の循環や生物の活動の変化も、酸素不足に影響します。温暖化、酸性化、酸素不足は関連しますが同じ現象ではありません。噴火と絶滅の年代、岩石の化学的記録を比べ、原因と結果のつながりを検討します。"),
        "camp-eruption" => ja("CAMPは中央大西洋マグマ活動の広大な地域を指す名前です。現在は離れた大陸に関連する岩石があるのは、当時それらがパンゲアとして近くにあったためです。大陸の分裂と火山活動の関係を、岩石の年代と位置から調べられます。\n\n三畳紀末の絶滅との関連では、ガスの放出による気候や海の変化が重要です。溶岩が直接すべての生物を焼いたという話ではありません。生態系が変わったあと、恐竜などが広く多様化しましたが、生き残った理由は個々のグループの生態と合わせて考える必要があります。"),
        "deccan-traps" => ja("デカンの台地には、何度も流れた溶岩が重なっています。「トラップ」は階段を意味する言葉に由来し、溶岩層がつくる地形に関係します。噴火は長い期間にわたり、放出されたガスは気候や海洋に影響を与えたと考えられます。\n\n白亜紀末の絶滅を考えるには、デカンの活動と小惑星衝突の時期を細かく比べる必要があります。長期の火山活動と短時間の衝突では、環境への影響の速さもちがいます。双方をひとまとめにせず、地層に残る温度変化や絶滅のタイミングから、役割を検討します。"),
        "chicxulub-impact" => ja("小惑星の衝突は、メキシコのユカタン半島付近に大きなクレーターを残しました。衝撃で変形した鉱物、イリジウムが多い境界の層、飛び散って固まった粒などが、衝突を示す証拠です。遠く離れた場所の地層も、同じ出来事を記録しています。\n\n空に舞い上がったちりや硫黄を含む粒子などが日光を減らすと、光合成が弱まり、食物網に影響が広がります。絶滅したのは鳥以外の恐竜だけではなく、海の生物にも大きな変化がありました。一方で、すべての生物が絶滅したわけではなく、生き残った生物が次の生態系をつくりました。"),
        _ => unreachable!("missing phenomenon reading: {slug}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_entry_has_substantial_readings_and_pronunciation_coverage() {
        for e in 0..life::n_entries() {
            let book = sections(e, Lang::Ja);
            assert!(book.len() >= 3, "{}", life::entry_slug(e));
            assert!(book.iter().map(|s| s.body.chars().count()).sum::<usize>() >= 600, "{}", life::entry_slug(e));
            for section in book {
                let spoken = crate::speech::text_for_speech(&section.body, Lang::Ja);
                let mut previous = false;
                for c in spoken.chars() {
                    let kanji = matches!(c, '一'..='龯' | '々');
                    assert!(!(kanji && previous), "missing reading: {}: {}", life::entry_slug(e), spoken);
                    previous = kanji;
                }
            }
        }
    }

    #[test]
    fn translations_preserve_the_original_individual_content() {
        for language in [Lang::En, Lang::Zh] {
            for e in 0..life::n_entries() {
                let book = sections(e, language);
                assert_eq!(book.len(), 1);
                assert!(!book[0].body.is_empty());
            }
        }
    }
}
